<?php require __DIR__.'/../src/bootstrap.php'; $app=new SignalPilot\Services\AppService(storage());$id=$_GET['id']??'';$do=$_GET['do']??'';try{if($do==='approve'){$t=$app->approve($id);echo '<h1>Trade approved</h1><p>Paper trade '.$t['id'].' created.</p>';}elseif($do==='deny'){$app->deny($id);echo '<h1>Opportunity denied</h1>';}else echo 'Missing action.';}catch(Throwable $e){http_response_code(400);echo e($e->getMessage());}
